//! Whole-plant production trace replay.
//!
//! The golden is generated by `scripts/gen-plant-replay.ts` from a real
//! `spinUpNetwork` + `stepNetwork(..., 15 min, trace)` run. For every step this
//! test reconstructs the exact module inputs captured inside the production
//! engine, runs the Rust kernels, and compares both the module outputs and the
//! published plant-level projections (effluent, inventory, biomass/SRT).

use aquapilot_core::adm1;
use aquapilot_core::asm2d::{Component, Params, State};
use aquapilot_core::network::{
    Edge, Influent, Network, Reactor, ReactorKind, Recycle, StepOptions,
};
use aquapilot_core::plant_boundary::{
    BalanceInput, BalanceRow, ComponentLoads, Inventory, InventoryInput, PlantBoundaryState,
    PlantError, WaterQuality,
};
use aquapilot_core::plant_replay::{
    BiomassInput, EffluentInput, ReactorInventory, asm2d_biomass, asm2d_inventory,
    production_effluent,
};
use aquapilot_core::sludge_line::{
    Cumulative, Dewatering, Digester, DigesterGas, Filtrate, SludgeFeed, SludgeLine, Thickener,
};
use aquapilot_core::takacs::{
    SettlerConfig, SettlerFeed, SettlerState, SettlerUnderflow, step_settler,
};
use serde_json::Value;
use std::fs;

// 96-step plant replay is a closed-loop production trajectory, not a single
// module slice. The observed worst absolute residual is 1.73e-9 across all
// states/fluxes; 1e-8 leaves ~5.8x numerical headroom without hiding any drift.
const TOL: f64 = 1e-8;

fn close(got: f64, want: f64, what: &str) {
    let diff = (got - want).abs();
    assert!(
        diff <= TOL,
        "{what}: got {got:.15e}, want {want:.15e}, abs diff {diff:.3e}"
    );
}

fn close_rel(got: f64, want: f64, what: &str) {
    let diff = (got - want).abs();
    let scale = got.abs().max(want.abs()).max(1.0);
    assert!(
        diff <= TOL * scale,
        "{what}: got {got:.15e}, want {want:.15e}, rel diff {:.3e}",
        diff / scale
    );
}

fn num(v: &Value, key: &str) -> f64 {
    v.get(key)
        .and_then(Value::as_f64)
        .unwrap_or_else(|| panic!("missing numeric field {key}"))
}

fn opt_num(v: &Value, key: &str) -> Option<f64> {
    v.get(key).and_then(Value::as_f64)
}

fn reactor_kind(s: &str) -> ReactorKind {
    match s {
        "anaerobic" => ReactorKind::Anaerobic,
        "anoxic" => ReactorKind::Anoxic,
        "aerobic" => ReactorKind::Aerobic,
        other => panic!("unknown reactor kind {other}"),
    }
}

fn component_key(c: Component) -> &'static str {
    match c {
        Component::SO => "S_O",
        Component::SF => "S_F",
        Component::SA => "S_A",
        Component::SI => "S_I",
        Component::SNH4 => "S_NH4",
        Component::SN2 => "S_N2",
        Component::SNO3 => "S_NO3",
        Component::SPO4 => "S_PO4",
        Component::SAlk => "S_ALK",
        Component::XI => "X_I",
        Component::XS => "X_S",
        Component::XH => "X_H",
        Component::XPAO => "X_PAO",
        Component::XPP => "X_PP",
        Component::XPHA => "X_PHA",
        Component::XAUT => "X_AUT",
        Component::XTSS => "X_TSS",
        Component::XMEOH => "X_MEOH",
        Component::XMEP => "X_MEP",
    }
}

fn asm2d_state(v: &Value) -> State {
    let mut state = State::zero();
    for c in aquapilot_core::asm2d::COMPONENTS {
        state.set(c, num(v, component_key(c)));
    }
    state
}

fn adm1_state(v: &Value) -> adm1::State {
    use adm1::Component as A;
    let map: [(A, &str); 27] = [
        (A::SSu, "S_su"),
        (A::SAa, "S_aa"),
        (A::SFa, "S_fa"),
        (A::SVa, "S_va"),
        (A::SBu, "S_bu"),
        (A::SPro, "S_pro"),
        (A::SAc, "S_ac"),
        (A::SH2, "S_h2"),
        (A::SCh4, "S_ch4"),
        (A::SIC, "S_IC"),
        (A::SIN, "S_IN"),
        (A::SI, "S_I"),
        (A::Xc, "X_c"),
        (A::Xch, "X_ch"),
        (A::Xpr, "X_pr"),
        (A::Xli, "X_li"),
        (A::Xsu, "X_su"),
        (A::Xaa, "X_aa"),
        (A::Xfa, "X_fa"),
        (A::Xc4, "X_c4"),
        (A::Xpro, "X_pro"),
        (A::Xac, "X_ac"),
        (A::Xh2, "X_h2"),
        (A::XI, "X_I"),
        (A::GH2, "G_h2"),
        (A::GCh4, "G_ch4"),
        (A::GCo2, "G_co2"),
    ];
    let mut state = adm1::empty_state();
    // Gas components are not in the dissolved object; leave them zero.
    for (c, key) in map {
        let value = v.get(key).and_then(Value::as_f64).unwrap_or(0.0);
        state.set(c, value);
    }
    state
}

fn gas(v: &Value) -> DigesterGas {
    DigesterGas {
        methane_m3d: num(v, "methaneM3d"),
        co2_m3d: num(v, "co2M3d"),
        h2_m3d: num(v, "h2M3d"),
        total_m3d: num(v, "totalM3d"),
        ch4_fraction: num(v, "ch4Fraction"),
        methane_kg_d: num(v, "methaneKgD"),
        vss_destroyed_kg_d: num(v, "vssDestroyedKgD"),
        heating_kw: num(v, "heatingKw"),
        mixing_kw: num(v, "mixingKw"),
    }
}

fn filtrate(v: &Value) -> Filtrate {
    Filtrate {
        flow_m3h: num(v, "flowM3h"),
        nh4_n_kg_m3: num(v, "nh4NKgM3"),
        cod_kg_m3: num(v, "codKgM3"),
        tp_kg_m3: num(v, "tpKgM3"),
    }
}

fn sludge_line(v: &Value) -> SludgeLine {
    let thick = &v["thickener"];
    let dig = &v["digester"];
    let dew = &v["dewatering"];
    let cum = &v["cumulative"];
    SludgeLine {
        enabled: v["enabled"].as_bool().unwrap_or(true),
        thickener: Thickener {
            feed_flow_m3h: num(thick, "feedFlowM3h"),
            feed_ss_kg_m3: num(thick, "feedSsKgM3"),
            underflow_flow_m3h: num(thick, "underflowFlowM3h"),
            underflow_ss_kg_m3: num(thick, "underflowSsKgM3"),
            supernatant_flow_m3h: num(thick, "supernatantFlowM3h"),
        },
        digester: Digester {
            volume_m3: num(dig, "volumeM3"),
            temperature_c: num(dig, "temperatureC"),
            srt_days: num(dig, "srtDays"),
            adm1: adm1_state(&dig["adm1"]),
            gas: gas(&dig["gas"]),
        },
        dewatering: Dewatering {
            cake_dry_solids_kg_d: num(dew, "cakeDrySolidsKgD"),
            cake_wet_kg_d: num(dew, "cakeWetKgD"),
            filtrate: filtrate(&dew["filtrate"]),
        },
        cumulative: Cumulative {
            raw_sludge_kg_d: num(cum, "rawSludgeKgD"),
            cake_kg_d: num(cum, "cakeKgD"),
            methane_m3: num(cum, "methaneM3"),
            filtrate_nh4_kg: num(cum, "filtrateNh4Kg"),
            filtrate_cod_kg: num(cum, "filtrateCodKg"),
            filtrate_tp_kg: num(cum, "filtrateTpKg"),
        },
        errors: vec![],
    }
}

fn assert_sludge_close(got: &SludgeLine, want: &SludgeLine, step: usize) {
    let prefix = format!("sludge step {step}");
    close(
        got.thickener.feed_flow_m3h,
        want.thickener.feed_flow_m3h,
        &format!("{prefix} thick feed flow"),
    );
    close(
        got.thickener.feed_ss_kg_m3,
        want.thickener.feed_ss_kg_m3,
        &format!("{prefix} thick feed ss"),
    );
    close(
        got.thickener.underflow_flow_m3h,
        want.thickener.underflow_flow_m3h,
        &format!("{prefix} thick uf flow"),
    );
    close(
        got.thickener.underflow_ss_kg_m3,
        want.thickener.underflow_ss_kg_m3,
        &format!("{prefix} thick uf ss"),
    );
    close(
        got.thickener.supernatant_flow_m3h,
        want.thickener.supernatant_flow_m3h,
        &format!("{prefix} thick sup flow"),
    );
    close(
        got.digester.volume_m3,
        want.digester.volume_m3,
        &format!("{prefix} dig volume"),
    );
    close(
        got.digester.temperature_c,
        want.digester.temperature_c,
        &format!("{prefix} dig temp"),
    );
    for (i, (g, w)) in got
        .digester
        .adm1
        .v
        .iter()
        .zip(want.digester.adm1.v.iter())
        .enumerate()
    {
        close(*g, *w, &format!("{prefix} adm1[{i}]"));
    }
    let g = got.digester.gas;
    let w = want.digester.gas;
    close(
        g.methane_m3d,
        w.methane_m3d,
        &format!("{prefix} gas methane"),
    );
    close(g.co2_m3d, w.co2_m3d, &format!("{prefix} gas co2"));
    close(g.h2_m3d, w.h2_m3d, &format!("{prefix} gas h2"));
    close(g.total_m3d, w.total_m3d, &format!("{prefix} gas total"));
    close(
        g.ch4_fraction,
        w.ch4_fraction,
        &format!("{prefix} gas ch4 frac"),
    );
    close(
        g.methane_kg_d,
        w.methane_kg_d,
        &format!("{prefix} gas methane kg"),
    );
    close(
        g.vss_destroyed_kg_d,
        w.vss_destroyed_kg_d,
        &format!("{prefix} gas vss"),
    );
    close(g.heating_kw, w.heating_kw, &format!("{prefix} gas heat"));
    close(g.mixing_kw, w.mixing_kw, &format!("{prefix} gas mix"));
    close(
        got.dewatering.cake_dry_solids_kg_d,
        want.dewatering.cake_dry_solids_kg_d,
        &format!("{prefix} cake dry"),
    );
    close(
        got.dewatering.cake_wet_kg_d,
        want.dewatering.cake_wet_kg_d,
        &format!("{prefix} cake wet"),
    );
    close(
        got.dewatering.filtrate.flow_m3h,
        want.dewatering.filtrate.flow_m3h,
        &format!("{prefix} filt flow"),
    );
    close(
        got.dewatering.filtrate.nh4_n_kg_m3,
        want.dewatering.filtrate.nh4_n_kg_m3,
        &format!("{prefix} filt nh"),
    );
    close(
        got.dewatering.filtrate.cod_kg_m3,
        want.dewatering.filtrate.cod_kg_m3,
        &format!("{prefix} filt cod"),
    );
    close(
        got.dewatering.filtrate.tp_kg_m3,
        want.dewatering.filtrate.tp_kg_m3,
        &format!("{prefix} filt tp"),
    );
    close(
        got.cumulative.raw_sludge_kg_d,
        want.cumulative.raw_sludge_kg_d,
        &format!("{prefix} cum raw"),
    );
    close(
        got.cumulative.cake_kg_d,
        want.cumulative.cake_kg_d,
        &format!("{prefix} cum cake"),
    );
    close(
        got.cumulative.methane_m3,
        want.cumulative.methane_m3,
        &format!("{prefix} cum methane"),
    );
    close(
        got.cumulative.filtrate_nh4_kg,
        want.cumulative.filtrate_nh4_kg,
        &format!("{prefix} cum fn"),
    );
    close(
        got.cumulative.filtrate_cod_kg,
        want.cumulative.filtrate_cod_kg,
        &format!("{prefix} cum fc"),
    );
    close(
        got.cumulative.filtrate_tp_kg,
        want.cumulative.filtrate_tp_kg,
        &format!("{prefix} cum ftp"),
    );
    let got_codes: Vec<&str> = got.errors.iter().map(|e| e.code).collect();
    let want_codes: Vec<&str> = want.errors.iter().map(|e| e.code).collect();
    assert_eq!(got_codes, want_codes, "{prefix} error codes");
}

fn balance_row(v: &Value) -> BalanceRow {
    BalanceRow {
        inflow_kg: num(v, "inflowKg"),
        effluent_kg: num(v, "effluentKg"),
        wasted_kg: num(v, "wastedKg"),
        methane_cod_kg: num(v, "methaneCodKg"),
        oxidized_kg: num(v, "oxidizedKg"),
        denitrified_kg: num(v, "denitrifiedKg"),
        inventory_change_kg: num(v, "inventoryChangeKg"),
        recycle_kg: num(v, "recycleKg"),
        residual_kg: num(v, "residualKg"),
        residual_pct: num(v, "residualPct"),
        closed: v["closed"].as_bool().unwrap_or(false),
    }
}

fn inventory(v: &Value) -> Inventory {
    Inventory {
        biomass_kg: num(v, "biomassKg"),
        cod_kg: num(v, "codKg"),
        n_kg: num(v, "nKg"),
        p_kg: num(v, "pKg"),
        previous_cod_kg: num(v, "previousCodKg"),
        previous_n_kg: num(v, "previousNKg"),
        previous_p_kg: num(v, "previousPKg"),
        seeded: v["seeded"].as_bool().unwrap_or(false),
    }
}

fn assert_row(got: &BalanceRow, want: &BalanceRow, what: &str) {
    close(got.inflow_kg, want.inflow_kg, &format!("{what} inflow"));
    close(
        got.effluent_kg,
        want.effluent_kg,
        &format!("{what} effluent"),
    );
    close(got.wasted_kg, want.wasted_kg, &format!("{what} wasted"));
    close(
        got.methane_cod_kg,
        want.methane_cod_kg,
        &format!("{what} methane"),
    );
    close(
        got.oxidized_kg,
        want.oxidized_kg,
        &format!("{what} oxidized"),
    );
    close(
        got.denitrified_kg,
        want.denitrified_kg,
        &format!("{what} denitrified"),
    );
    close(
        got.inventory_change_kg,
        want.inventory_change_kg,
        &format!("{what} inventory delta"),
    );
    close(got.recycle_kg, want.recycle_kg, &format!("{what} recycle"));
    close(
        got.residual_kg,
        want.residual_kg,
        &format!("{what} residual"),
    );
    close(
        got.residual_pct,
        want.residual_pct,
        &format!("{what} residual pct"),
    );
    assert_eq!(got.closed, want.closed, "{what} closed flag");
}

fn assert_inventory(got: &Inventory, want: &Inventory, what: &str) {
    close(got.biomass_kg, want.biomass_kg, &format!("{what} biomass"));
    close(got.cod_kg, want.cod_kg, &format!("{what} cod"));
    close(got.n_kg, want.n_kg, &format!("{what} n"));
    close(got.p_kg, want.p_kg, &format!("{what} p"));
    close(
        got.previous_cod_kg,
        want.previous_cod_kg,
        &format!("{what} prev cod"),
    );
    close(
        got.previous_n_kg,
        want.previous_n_kg,
        &format!("{what} prev n"),
    );
    close(
        got.previous_p_kg,
        want.previous_p_kg,
        &format!("{what} prev p"),
    );
    assert_eq!(got.seeded, want.seeded, "{what} seeded");
}

